#include <iostream>

// Cách tiếp cận truyền thống C
#define OLD_PI 3.14159

// Cách tiếp cận chuẩn C++17 an toàn kiểu
inline constexpr double MODERN_PI = 3.141592653589793;
inline constexpr int MAX_BUFFER = 1024;

int main() {
    double radius = 2.5;

    double areaOld = OLD_PI * radius * radius;
    double areaModern = MODERN_PI * radius * radius;

    std::cout << "Old Area: " << areaOld << "\n";
    std::cout << "Modern Area: " << areaModern << "\n";
    std::cout << "Buffer Capacity: " << MAX_BUFFER << "\n";

    return 0;
}

#include <iostream>

#define SAFE_RECT(x, y) (((x)) * ((y)))
#define FLAWED_RECT(x, y) x * y

template <typename T>
constexpr auto modernRect(T x, T y) noexcept {
    return x * y;
}

int main() {
    int a = 2;
    int b = 3;

    // Tính diện tích hình chữ nhật kích thước (a + 1) x (b + 2) = 3 x 5 = 15
    int flawedResult = FLAWED_RECT(a + 1, b + 2); // 2 + 1 * 3 + 2 = 2 + 3 + 2 = 7
    int safeResult = SAFE_RECT(a + 1, b + 2);     // ((2 + 1)) * ((3 + 2)) = 15
    int modernResult = modernRect(a + 1, b + 2);  // hàm đánh giá tham số trước = 15

    std::cout << "Flawed Macro Result: " << flawedResult << "\n";
    std::cout << "Safe Macro Result: " << safeResult << "\n";
    std::cout << "Modern C++ Result: " << modernResult << "\n";

    return 0;
}
